package android.text;
public class Html {public static Spanned fromHtml(String text){return new Text(text.replace("<br>","\n"));}static class Text implements Spanned {final String text;Text(String t){text=t;}public int length(){return text.length();}public char charAt(int n){return text.charAt(n);}public CharSequence subSequence(int a,int b){return text.subSequence(a,b);}public String toString(){return text;}public <T>T[] getSpans(int a,int b,Class<T> kind){return (T[])java.lang.reflect.Array.newInstance(kind,0);}public int getSpanStart(Object tag){return -1;}public int getSpanEnd(Object tag){return -1;}public int getSpanFlags(Object tag){return 0;}public int nextSpanTransition(int start,int end,Class kind){return end;}}}
